// MARK: - GraphqlRequest
public struct GraphqlRequest: Codable, Sendable {
    /// The name of the operation to execute
    public let operationName: String?
    /// The GraphQL query or mutation string
    public let query: String
    /// The variables for the GraphQL operation
    public let variables: [String: JSONValue]?

    public init(operationName: String? = nil, query: String, variables: [String: JSONValue]? = nil) {
        self.operationName = operationName
        self.query = query
        self.variables = variables
    }
}

// MARK: - GraphqlResponse
public struct GraphqlResponse: Codable, Sendable {
    /// The data returned by the GraphQL operation
    public let data: [String: JSONValue]?
    /// Any errors returned by the GraphQL operation
    public let errors: [GraphqlResponseError]?

    public init(data: [String: JSONValue]? = nil, errors: [GraphqlResponseError]? = nil) {
        self.data = data
        self.errors = errors
    }
}

// MARK: - GraphqlResponseError
public struct GraphqlResponseError: Codable, Sendable {
    public let message: String?

    public init(message: String? = nil) {
        self.message = message
    }
}

