    }
}

public enum FileUploadRequestFile: Codable, Sendable {
    case fileUploadRequestObject2File(FileUploadRequestObject2File)
    case string(String)

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode(String.self) {
            self = .string(x)
            return
        }
        if let x = try? container.decode(FileUploadRequestObject2File.self) {
            self = .fileUploadRequestObject2File(x)
            return
        }
        throw DecodingError.typeMismatch(FileUploadRequestFile.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for FileUploadRequestFile"))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .fileUploadRequestObject2File(let x):
            try container.encode(x)
        case .string(let x):
            try container.encode(x)
        }
    }
}

