public enum DatasetFilterValue: Codable, Sendable {
    case bool(Bool)
    case datasetFilterValueObject(DatasetFilterValueObject)
    case double(Double)
    case string(String)

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode(Bool.self) {
            self = .bool(x)
            return
        }
        if let x = try? container.decode(Double.self) {
            self = .double(x)
            return
        }
        if let x = try? container.decode(String.self) {
            self = .string(x)
            return
        }
        if let x = try? container.decode(DatasetFilterValueObject.self) {
            self = .datasetFilterValueObject(x)
            return
        }
        throw DecodingError.typeMismatch(DatasetFilterValue.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for DatasetFilterValue"))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .bool(let x):
            try container.encode(x)
        case .datasetFilterValueObject(let x):
            try container.encode(x)
        case .double(let x):
            try container.encode(x)
        case .string(let x):
            try container.encode(x)
        }
    }
}

