    public let instructions: StringOrObjectOrArray
    public let type: DecisionQuestionType

    public init(criteria: DecisionQuestionCriteria? = nil, instructions: StringOrObjectOrArray, type: DecisionQuestionType) {
        self.criteria = criteria
        self.instructions = instructions
        self.type = type
    }
}

public enum DecisionQuestionCriteria: Codable, Sendable {
    case decisionQuestionBooleanCriteria(DecisionQuestionBooleanCriteria)
    case unionArray([StringOrObjectOrArray])

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode([StringOrObjectOrArray].self) {
            self = .unionArray(x)
            return
        }
        if let x = try? container.decode(DecisionQuestionBooleanCriteria.self) {
            self = .decisionQuestionBooleanCriteria(x)
            return
        }
        throw DecodingError.typeMismatch(DecisionQuestionCriteria.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for DecisionQuestionCriteria"))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .decisionQuestionBooleanCriteria(let x):
            try container.encode(x)
        case .unionArray(let x):
            try container.encode(x)
        }
    }
}

